{"code": "import requests
import json
from datetime import datetime

API_URL = "https://en.wikipedia.org/w/api.php"
headers = {
    'User-Agent': 'Mozilla/5.0 (research bot; twitter_citation_counting@example.com)'
}

def get_revisions(title, limit=500):
    """Get revision history for a page"""
    params = {
        'action': 'query',
        'format': 'json',
        'titles': title,
        'prop': 'revisions',
        'rvprop': 'timestamp',
        'rvlimit': limit
    }
    response = requests.get(API_URL, params=params, headers=headers)
    data = response.json()
    pages = data['query']['pages']
    for page_id in pages:
        return pages[page_id].get('revisions', [])
    return []

# Get revisions for August 1 to see the structure
revisions = get_revisions("August 1", limit=500)
print(f"Total revisions returned: {len(revisions)}")
print("\nFirst 5 revisions (most recent):")
for r in revisions[:5]:
    print(f"  {r['timestamp']}")

print("\nLast 5 revisions (oldest in this batch):")
for r in revisions[-5:]:
    print(f"  {r['timestamp']}")"}
